import { execFileSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { it } from 'vitest';
import { observeCodeStructure as observeNew } from './code-structure.js';
import { observeCodeStructure as observeOld } from './zz-code-structure-old.js';

// Each case is one revision's listing in both formats: what git prints without -z (old asks for it) and with -z (new).
interface Case { readonly id: string; readonly plain: string; readonly z: string }
const id40 = 'a'.repeat(40);
const rec = (path: string, id = id40, size = '12', type = 'blob', mode = '100644'): string => `${mode} ${type} ${id} ${size.padStart(7)}\t${path}`;
const both = (id: string, records: readonly string[], plainPaths?: readonly string[]): Case => ({
  id, plain: records.map((r, i) => (plainPaths?.[i] === undefined ? r : r.replace(/\t.*$/s, `\t${plainPaths[i]}`))).join('\n') + '\n', z: records.join('\0') + '\0',
});

it('old versus new over a mutated ls-tree corpus', () => {
  const root = mkdtempSync(join(tmpdir(), 'bpyt61-diff-'));
  const names = ['plain.ts', 'with space.md', 'tab\there.md', 'a "b".txt', 'ñ.md', 'line\nbreak.md', '"lead-quote.md', 'back\\slash.ts'];
  for (const name of names) { mkdirSync(dirname(join(root, name)), { recursive: true }); writeFileSync(join(root, name), 'x\n'); }
  const g = (...args: string[]): string => execFileSync('git', ['-C', root, ...args], { encoding: 'utf8' });
  g('init', '-q'); g('-c', 'user.email=t@e.invalid', '-c', 'user.name=t', 'add', '-A'); g('-c', 'user.email=t@e.invalid', '-c', 'user.name=t', 'commit', '-qm', 'x');
  const realPlain = g('ls-tree', '-r', '-l', 'HEAD'), realZ = g('ls-tree', '-r', '-z', '-l', 'HEAD');
  const realPlainLines = realPlain.split('\n').filter(Boolean), realZRecords = realZ.split('\0').filter(Boolean);
  const cases: Case[] = [
    { id: 'real repo: all eight awkward names', plain: realPlain, z: realZ },
    ...realZRecords.map((record, i) => ({ id: `real repo: only ${JSON.stringify(record.slice(record.indexOf('\t') + 1))}`, plain: realPlainLines[i]! + '\n', z: record + '\0' })),
    both('one plain blob', [rec('a.ts')]),
    both('submodule gitlink beside a blob', [rec('a.ts'), rec('vendor/sub', 'b'.repeat(40), '-', 'commit', '160000')]),
    both('blob without a size', [rec('a.ts', id40, '-')]),
    both('SHA-256 object id', [rec('a.ts', 'c'.repeat(64))]),
    both('39-hex object id', [rec('a.ts', 'c'.repeat(39))]),
    both('garbage record after a blob', [rec('a.ts'), 'not a tree record']),
    both('mode corrupted', [rec('a.ts', id40, '12', 'blob', '10064x')]),
    both('type corrupted', [rec('a.ts', id40, '12', 'blbo')]),
    both('tab separator missing', [rec('a.ts').replace('\t', ' ')]),
    both('empty path', [rec('')]),
    both('size non-numeric', [rec('a.ts', id40, '1e3')]),
    both('uppercase hex id', [rec('a.ts', 'A'.repeat(40))]),
    both('symlink blob', [rec('link', id40, '4', 'blob', '120000')]),
    both('executable blob', [rec('run.sh', id40, '4', 'blob', '100755')]),
    { id: 'empty tree', plain: '', z: '' },
  ];
  const outcome = (r: ReturnType<typeof observeNew>): string => r.kind === 'unknown' ? `Unknown (${r.reason})` : `Observed ${r.files.length}: ${JSON.stringify(r.files.map((f) => [f.path, f.sizeBytes, f.digest.slice(0, 18), f.language]))}`;
  const run = (observe: typeof observeNew, listing: string, want: boolean) => observe({ repoRoot: '/unused', revision: 'r', capturedAt: 't', runGit: (_root, args) => { if (args.includes('-z') !== want) throw new Error(`asked ${args.join(' ')}`); return listing; } });
  const rows = cases.map((c) => { const o = outcome(run(observeOld, c.plain, false)); const n = outcome(run(observeNew, c.z, true)); return { case: c.id, old: o, new: n, changed: o !== n }; });
  writeFileSync(process.env['B61_DIFF']!, JSON.stringify(rows, null, 1));
});
